mapper.insert:
INSERT INTO crm_survey_outreach_log (
    survey_id, channel, recipient_type, recipient_id, task_id, status, sent_at
) VALUES (
    #{surveyId}, #{channel}, #{recipientType}, #{recipientId}, #{taskId}, #{status},
    COALESCE(#{sentAt}, CURRENT_TIMESTAMP)
)

mapper.select:
SELECT id AS id, survey_id AS surveyId, channel AS channel, recipient_type AS recipientType, recipient_id AS recipientId, status AS status, sent_at AS sentAt FROM crm_survey_outreach_log WHERE survey_id = #{surveyId}
AND recipient_id = #{recipientId}
AND channel = #{channel}
ORDER BY sent_at DESC

SELECT COUNT(*)
FROM crm_survey_outreach_log
WHERE survey_id = #{surveyId}
  AND channel = #{channel}
  AND status = 'sent'
